PROVENANCE = "original practice wording for the five-topic interview, not an actual company question"


def additional_questions():
    """Return immutable migration seed rows for the second batch."""
    references = {"behavioral": AMAZON_GUIDE, "algorithms": GOOGLE_GUIDE, "system-design": SYSTEM_SOURCE}
    rows = []
    for key, focus, topic, english, ukrainian in QUESTIONS:
        for language, question in (("en", english), ("uk", ukrainian)):
            rows.append({"key": key, "version": 1, "language": language, "focus": focus,
                         "topic_index": topic, "role": "*", "level": "*", "question": question,
                         "criteria": CRITERIA[focus][language], "source_url": references[focus],
                         "provenance": PROVENANCE, "active": True})
    return rows
